import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of an owned scalar ledger; no AI counters or gameplay calculators change. */
public final class SourceDamageCapacityDelta {
 static final String P="local/lito381/server/",N=P+"NativeSourceDamageCapacity",LIFE=P+"NativePlayerLifetime",PCQ=P+"NativePlayerCommit$Queue",NPC=P+"NativeNpcLifetime",SLOT=P+"NativeSourcePendingAdmission",ATOMIC="java/util/concurrent/atomic/AtomicLong",FIELD="nativeSourceDamagePending";
 static void need(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static List<AbstractInsnNode> ops(MethodNode m){return Arrays.stream(m.instructions.toArray()).filter(x->x.getOpcode()>=0).toList();}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=List.of(LIFE,PCQ,NPC,SLOT);var entries=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){entries.add(e.getName());var x=jar.getJarEntry(e.getName());need(x!=null,"no removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(x).readAllBytes()))changed.add(e.getName());}need(changed.equals(names.stream().map(x->x+".class").collect(java.util.stream.Collectors.toSet())),"four exact existing classes; all AI/calculator/SQL classes retained");int methods=0,init=0,idle=0,rewired=0,work=0,releases=0,wrapper=0;
 for(var name:names){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(now.fields.size()==old.fields.size()+(name.equals(LIFE)?1:0),"one owner scalar field");for(int i=0;i<old.fields.size();i++){var x=old.fields.get(i);var y=now.fields.get(i);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields unchanged");}if(name.equals(LIFE)){var f=now.fields.get(now.fields.size()-1);need(f.name.equals(FIELD)&&f.desc.equals("Ljava/util/concurrent/atomic/AtomicLong;")&&f.access==ACC_FINAL,"original owner owns one final atomic counter");}
  for(var before:old.methods){var alias=name.equals(SLOT)&&before.name.equals("offer")?"nativeSourceDamageCapacityOriginalOffer":before.name;var after=now.methods.stream().filter(x->x.name.equals(alias)&&x.desc.equals(before.desc)).findFirst().orElseThrow();
   if(name.equals(LIFE)&&before.name.equals("<init>")){for(var node:after.instructions.toArray())if(node instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.name.equals(FIELD)){var ctor=FreezeAcceptedMethods.prev(node);var dup=FreezeAcceptedMethods.prev(ctor);var allocated=FreezeAcceptedMethods.prev(dup);var self=FreezeAcceptedMethods.prev(allocated);need(self instanceof VarInsnNode v&&v.var==0&&allocated instanceof TypeInsnNode t&&t.getOpcode()==NEW&&t.desc.equals(ATOMIC)&&dup.getOpcode()==DUP&&ctor instanceof MethodInsnNode c&&c.owner.equals(ATOMIC)&&c.name.equals("<init>"),"fresh zero counter in original constructor");for(var x:List.of(self,allocated,dup,ctor,node))after.instructions.remove(x);init++;}}
   for(var node:after.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)){
    if(call.name.equals("idle")){need(name.equals(LIFE)&&Set.of("idle","terminated").contains(before.name),"original idle fence only");var x=ops(after).subList(0,5);need(x.get(1)==call&&x.get(2).getOpcode()==IFNE&&x.get(3).getOpcode()==ICONST_0&&x.get(4).getOpcode()==IRETURN,"reject-only scalar idle prefix");for(var op:x)after.instructions.remove(op);idle++;}
    else if(call.name.equals("release")){boolean pc=name.equals(PCQ);boolean drop=before.name.equals(pc?"drop":"clearing");need(pc?Set.of("claim","drop").contains(before.name):Set.of("claimed","clearing").contains(before.name),"original dequeue/drop only");var amount=FreezeAcceptedMethods.prev(call);var first=FreezeAcceptedMethods.prev(amount);if(drop){need(amount.getOpcode()==I2L&&first instanceof VarInsnNode n&&n.getOpcode()==ILOAD&&n.var==(pc?2:3),"exact original dropped count");first=FreezeAcceptedMethods.prev(first);}else need(amount.getOpcode()==LCONST_1,"one original dequeued event");var owner=first;var self=FreezeAcceptedMethods.prev(owner);need(owner instanceof FieldInsnNode f&&f.name.equals("life")&&f.owner.equals(pc?PCQ:NPC+"$Lane")&&self instanceof VarInsnNode v&&v.var==(pc?0:2),"original application owner");var stop=call.getNext();for(var n=self;n!=stop;){var next=n.getNext();after.instructions.remove(n);n=next;}releases++;}
    else throw new AssertionError("unexpected original port "+call.name);
   }
   if(name.equals(PCQ)&&before.name.equals("nativeFreezeAcceptedOriginalOffer")){
    for(var node:after.instructions.toArray())if(node instanceof FieldInsnNode f&&f.owner.equals(LIFE)&&f.name.equals(FIELD)){f.name="pending";rewired++;}
    // Restore the predecessor, which had reserved the work counter before publication.
    int removed=0;for(var node:after.instructions.toArray())if(node instanceof FieldInsnNode f&&f.owner.equals(LIFE)&&f.name.equals("pending")){var inc=FreezeAcceptedMethods.next(node);if(inc instanceof MethodInsnNode c&&c.name.equals("incrementAndGet")){var owner=FreezeAcceptedMethods.prev(node);var self=FreezeAcceptedMethods.prev(owner);var pop=FreezeAcceptedMethods.next(inc);need(self instanceof VarInsnNode v&&v.var==0&&owner instanceof FieldInsnNode o&&o.owner.equals(PCQ)&&o.name.equals("life")&&pop.getOpcode()==POP2,"one original-work credit publication");for(var x:List.of(self,owner,node,inc,pop))after.instructions.remove(x);removed++;}}
    need(removed==1,"one work credit added separately from reservation");work++;
   }
   after.name=before.name;need(before.access==after.access&&before.desc.equals(after.desc),"original monitor/signature");need(Arrays.equals(FreezeSourceTargetDelta.body(old,before,before.name,before.access),FreezeSourceTargetDelta.body(now,after,before.name,before.access)),"independent original inverse "+name+'.'+before.name);methods++;
  }
  need(now.methods.size()==old.methods.size()+(name.equals(SLOT)?1:0),"only one bounded wrapper");if(name.equals(SLOT)){var duplicate=now.methods.stream().filter(m->m.name.equals("offer")).toList();need(duplicate.size()==2,"retained predecessor and one wrapper");var x=ops(duplicate.get(1));need(x.size()==5&&x.get(3)instanceof MethodInsnNode call&&call.owner.equals(N)&&call.name.equals("offer")&&x.get(4).getOpcode()==IRETURN,"exact new damage-only delegate");wrapper++;}
 }
 need(init==1&&idle==2&&rewired==2&&work==1&&releases==4&&wrapper==1,"exact owner/reservation/publication/dequeue/drop ports");int fresh=0,aliasCalls=0;for(var e:Collections.list(jar.entries()))if(e.getName().endsWith(".class")){var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));if(!entries.contains(e.getName())){need(c.name.equals(N),"one scalar helper only");fresh++;need(c.fields.isEmpty(),"no retained actor/session/registry");for(var m:c.methods)for(var node:m.instructions){if(node instanceof FieldInsnNode f)need(!(f.owner.equals(LIFE)&&f.name.equals("admission")),"no queue-admission inversion");if(node instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor")&&!t.desc.contains("Timer"),"no worker/timer/TLS");if(node instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("Repository")&&!call.owner.contains("GameStateStore"),"no persistence");}}for(var m:c.methods)for(var node:m.instructions)if(node instanceof MethodInsnNode call&&call.owner.equals(SLOT)&&call.name.equals("nativeSourceDamageCapacityOriginalOffer"))aliasCalls++;}
 need(fresh==1&&aliasCalls==0,"one helper and no reachable predecessor offer");System.out.println("PASS independent damage-capacity inverse: "+methods+" original methods; AI/work credits retained, one damage ledger per owner, exact PC/NPC reserve/dequeue/drop and idle fence, Source constants retained");}}
}
